// One business event. In production this is the order that arrived on a
// webhook, not a value invented inside the workflow.
return [{ json: { orderId: 'ORD-10042', amountCents: 4900, currency: 'EUR' } }];

// httpbin echoes the request back. Read the key the server actually saw.
return $input.all().map(item => ({
  json: {
    keyServerReceived: item.json.headers?.['Idempotency-Key'] ?? null,
    bodyServerReceived: item.json.json ?? null
  }
}));
